\documentclass{article}
\usepackage{pgfplots, pgfplotstable}
\pgfplotsset{compat=1.8}

\usepackage{amsmath}


\pgfplotstablenew{201}\loadedtable

\begin{document}
\pagestyle{empty}
	\begin{tikzpicture}
	\begin{axis}[
	xlabel = $x$,
	ylabel = {$y$},
	xlabel style={below},
	ylabel style={rotate=-90},
	view={0}{90},
	domain=-1:4,
	y domain=-3:4,
	xmax=3, ymax=4,
	samples=28,
    /pgf/declare function={L=0.18;}
	]
	\addplot3 [gray, quiver={u={L*1/sqrt(1^2+(-0.1*(y+2)^2*(y-1)*(y-3))^2)}, v={L*-0.1*(y+2)^2*(y-1)*(y-3)/sqrt(1^2+(-0.1*(y+2)^2*(y-1)*(y-3))^2)}, scale arrows=1}] (x,y,0);

	\end{axis}
	\end{tikzpicture}

	\end{document}
